se_amount_yuan","type":"number"},{"name":"current_amount_yuan","type":"number"},{"name":"change_amount_yuan","type":"number"},{"name":"change_rate","type":"number"},{"name":"change_amount_wan_yuan","type":"number"}],"rowCount":7,"sql":"const grouped = stat.groupBy(data, 'channel');
const result = Object.keys(grouped).map(ch => {
  const items = grouped[ch];
  const baseItems = stat.filter(items, d => d.period === '基期');
  const currentItems = stat.filter(items, d => d.period === '本期');

  const baseCents = baseItems.length > 0 ? stat.sum(baseItems, 'contribution_cents') : 0;
  const currentCents = currentItems.length > 0 ? stat.sum(currentItems, 'contribution_cents') : 0;

  const base_amount_yuan = baseCents / 100;
  const current_amount_yuan = currentCents / 100;
  const change_amount_yuan = current_amount_yuan - base_amount_yuan;
